results.push('integ boundary: ' + await tools.Edit({ file_path: integ,
  old_str: '   write-token question; M4→M5: reference CSV presence), and the screenshot path to request.',
  new_str: '   write-token question; M4→M5: reference CSV presence), and the screenshot path to request. Report to the\n   orchestrator through the handoff only; never address the human (owner communication rule): the\n   orchestrator relays one line of status and three-line decision requests.' }));
results.push('integ pending: ' + await tools.Edit({ file_path: integ,
  old_str: '   `make decisions-index` if a decision file arrived\n   without an index update. Markdown must pass `make check-docs check-links`.',
  new_str: '   `make decisions-index` if a decision file arrived\n   without an index update. Pending owner edits listed in `library/integration-and-boundaries.md`\n   ("Pending integration edits") are applied here. Markdown must pass `make check-docs check-links`.' }));
results.forEach(r => text(r));

